-- GuinchaFacil - pacote estrategico idempotente
-- Reconcilia produtos por SKU e metas por codigo de zona.
-- Nao altera usuarios, pedidos, pagamentos ou historico.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE pricing_zones SET meta_guinchos_min=4, meta_especialistas_min=6 WHERE code='niteroi-celula-1';
UPDATE pricing_zones SET meta_guinchos_min=COALESCE(meta_guinchos_min,4), meta_especialistas_min=COALESCE(meta_especialistas_min,6) WHERE code='niteroi-celula-1';
COMMIT;
-- Fim do pacote idempotente.
